@forelse($entries as $entry)<section><h2>{{ $entry['work_date'] }} · {{ ucfirst($entry['hr_status']) }}</h2><div class="summary"><span>Clock: {{ $entry['time_in'] ?: '—' }} – {{ $entry['time_out'] ?: '—' }}</span><span>Work: <strong>{{ $duration($entry['working_seconds']) }}</strong></span><span>Break: {{ $duration($entry['break_seconds']) }}</span><span>Tasks: {{ $duration($entry['task_seconds']) }}</span></div><p>Location: {{ $entry['work_location'] ?: 'Not recorded' }} · Meetings: {{ $entry['meetings'] ?? '—' }} · People assisted: {{ $entry['people_assisted'] ?? '—' }}</p><table><thead><tr><th>Task</th><th>Time</th><th>Category / reference</th><th>Status</th></tr></thead><tbody>@foreach($entry['tasks'] ?? [] as $task)<tr><td>{{ $task['task'] ?? $task['description'] ?? '' }}</td><td>{{ $task['start'] ?? '—' }} – {{ $task['end'] ?? '—' }}</td><td>{{ $task['category'] ?? '—' }} / {{ $task['reference'] ?? '—' }}</td><td>{{ str_replace('_',' ',$task['status'] ?? '') }}</td></tr>@endforeach</tbody></table>@foreach(['blockers'=>'Blockers','tomorrow'=>'Plans for tomorrow','remarks'=>'Notes'] as $key=>$label)@if($entry[$key])<p><strong>{{ $label }}:</strong> {{ $entry[$key] }}</p>@endif @endforeach
@if($entry['submitted_at'])<p class="muted">Declared by {{ $entry['declared_name'] }} at {{ $entry['submitted_at'] }} · Revision {{ $entry['hr_version'] }}</p>@else<p class="muted">{{ $entry['hr_status']==='legacy' ? 'Historical record. No digital declaration recorded.' : 'Not submitted.' }}</p>@endif</section>@empty<p>No time records for this period.</p>@endforelse
@if($weekly)<section><h2>Weekly declaration</h2>@if($signoff)<p>Status: {{ $signoff->status }} · Signed {{ $signoff->signed_at }} · Revision {{ $signoff->version }}</p>@if($signoff->reviewed_at)<p>Reviewed {{ $signoff->reviewed_at }}{{ $signoff->review_comment ? ' · '.$signoff->review_comment : '' }}</p>@endif @else<p>No weekly declaration recorded.</p>@endif</section>@endif<footer class="muted">Luv, eP. · Private employee record · Generated {{ now('UTC')->format('Y-m-d H:i') }} UTC</footer></body></html>
